    fn v2_db(name: &str, snapshots: &[(i64, String)]) -> TempDb {
        let db = TempDb::new(name);
        let conn = Connection::open(db.path()).unwrap();
        conn.execute_batch(&format!(
            "{SCHEMA_V1} {HIST_BY_AGGREGATION} PRAGMA user_version = 2;"
