//! OS 別のディレクトリ解決。Linux は XDG Base Directory Specification に従う。

use anyhow::{Context, Result, anyhow};
use std::path::{Path, PathBuf};

#[derive(Debug, Clone, PartialEq)]
pub struct Paths {
    pub config_dir: PathBuf,
    pub data_dir: PathBuf,
    pub incidents_dir: PathBuf,
    pub logs_dir: PathBuf,
    pub reports_dir: PathBuf,
    pub lock_dir: PathBuf,
    /// XDG_RUNTIME_DIR が無くロックを state 側へ退避したとき true
    pub lock_fallback: bool,
}

impl Paths {
    pub fn config_file(&self) -> PathBuf {
        self.config_dir.join("config.toml")
    }

    pub fn db_file(&self) -> PathBuf {
        self.data_dir.join("kuda.db")
    }

    pub fn lock_file(&self) -> PathBuf {
        self.lock_dir.join("kuda.lock")
    }

    pub fn from_env() -> Result<Self> {
        Self::resolve(cfg!(windows), |key| std::env::var(key).ok())
    }

    fn resolve(windows: bool, env: impl Fn(&str) -> Option<String>) -> Result<Self> {
        let var = |key: &str| env(key).filter(|v| !v.is_empty());

        if let Some(home) = var("KUDA_HOME") {
            let root =
                std::path::absolute(&home).with_context(|| format!("invalid KUDA_HOME: {home}"))?;
            return Ok(Self::single_root(root));
        }
        if windows {
            // 設定はユーザーに付いて回るもの、それ以外はこの PC に固有のもの
            let roaming = var("APPDATA").ok_or_else(|| anyhow!("APPDATA is not set"))?;
            let local = var("LOCALAPPDATA").ok_or_else(|| anyhow!("LOCALAPPDATA is not set"))?;
            return Ok(Self {
                config_dir: PathBuf::from(roaming).join("kuda"),
                ..Self::single_root(PathBuf::from(local).join("kuda"))
            });
        }

        let home = var("HOME").ok_or_else(|| anyhow!("HOME is not set"))?;
        // 仕様どおり、相対パスの値は無効として既定値へ戻す
        let xdg = |key: &str, default: &str| {
            var(key)
                .map(PathBuf::from)
                .filter(|p| p.is_absolute())
                .unwrap_or_else(|| Path::new(&home).join(default))
                .join("kuda")
        };
        let state = xdg("XDG_STATE_HOME", ".local/state");
        let runtime = var("XDG_RUNTIME_DIR")
            .map(PathBuf::from)
            .filter(|p| p.is_absolute());

        Ok(Self {
            config_dir: xdg("XDG_CONFIG_HOME", ".config"),
            incidents_dir: state.join("incidents"),
            logs_dir: state.join("logs"),
            reports_dir: xdg("XDG_DATA_HOME", ".local/share").join("reports"),
            lock_fallback: runtime.is_none(),
            lock_dir: runtime.map_or_else(|| state.join("run"), |dir| dir.join("kuda")),
            data_dir: state,
        })
    }

    fn single_root(root: PathBuf) -> Self {
        Self {
            data_dir: root.join("data"),
            lock_dir: root.join("data"),
            incidents_dir: root.join("incidents"),
            logs_dir: root.join("logs"),
            reports_dir: root.join("reports"),
            config_dir: root,
            lock_fallback: false,
        }
    }

    /// 書き込み先のディレクトリを用意する
    pub fn ensure_dirs(&self) -> Result<()> {
        for dir in [
            &self.data_dir,
            &self.incidents_dir,
            &self.logs_dir,
            &self.reports_dir,
            &self.lock_dir,
        ] {
            create_private_dir(dir)?;
        }
        Ok(())
    }
}

/// 無ければ 0700 で作成する。既にあるディレクトリのパーミッションは変えない
pub fn create_private_dir(dir: &Path) -> Result<()> {
    let mut builder = std::fs::DirBuilder::new();
    builder.recursive(true);
    #[cfg(unix)]
    {
        use std::os::unix::fs::DirBuilderExt;
        builder.mode(0o700);
    }
    builder
        .create(dir)
        .with_context(|| format!("failed to create {}", dir.display()))
}

/// 1 つのパス要素としてそのまま使える名前か。区切り文字や `..` を通さないよう文字種を絞る
pub fn is_safe_name(name: &str) -> bool {
    !name.is_empty()
        && name
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || c == '-' || c == '_')
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::HashMap;

    fn resolve(windows: bool, vars: &[(&str, &str)]) -> Result<Paths> {
        let vars: HashMap<String, String> = vars
            .iter()
            .map(|(k, v)| (k.to_string(), v.to_string()))
            .collect();
        Paths::resolve(windows, |key| vars.get(key).cloned())
    }

    // Windows 上で実行しても比較が成り立つよう、期待値も join で組み立てる
//! 時間帯別 p50/p95 の統計ベースライン。
//!
//! weekday_hour の 1 区画は 5 分間隔でも週に 12 サンプルしか増えないので、
//! metrics_retention（既定 7 日）の生データからは min_samples に届かない。
//! そのため対数ビンのヒストグラムとして、保持期間と無関係に蓄積する。
//! 百分位数の誤差はビン幅の半分（約 ±2.5%）に収まる。

use crate::config::{AggregateBy, Baseline};
use crate::store::{Store, V1Hist};
use crate::trigger::Variables;
use anyhow::Result;
use chrono::{DateTime, Datelike, Local, TimeZone, Timelike};

/// (ヒストグラムの系列名, 元になる指標)。
/// 系列 rtt は probe ごとの中央値の分布で、`baseline.rtt_p95` はその 95 パーセンタイル
const SERIES: [(&str, &str); 3] = [("rtt", "rtt_p50"), ("loss", "loss"), ("value", "value")];

/// 隣り合うビンの比
const BIN_RATIO: f64 = 1.05;

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Source {
    /// 同じ時間帯の統計
    Bucket,
    /// 時間帯のサンプルが足りず、全体の統計で代用した
    Overall,
}

#[derive(Debug, Clone, PartialEq)]
pub struct SeriesStats {
    pub series: &'static str,
    pub source: Source,
    pub samples: u64,
    pub p50: f64,
    pub p95: f64,
}

/// 永続化する集計方式の名前。bucket の値は同じ方式の中でしか比べられない
fn aggregation_key(aggregate_by: AggregateBy) -> &'static str {
    match aggregate_by {
        AggregateBy::WeekdayHour => "weekday_hour",
        AggregateBy::Hour => "hour",
        AggregateBy::None => "none",
    }
}

/// 集計方式がとりうる bucket の最大値
fn max_bucket(aggregate_by: AggregateBy) -> i64 {
    match aggregate_by {
        AggregateBy::WeekdayHour => 7 * 24 - 1,
        AggregateBy::Hour => 23,
        AggregateBy::None => 0,
    }
}

/// 集計方式を記録していなかった版の分布を、移行後に初めて使う時点の方式で記録したものとして引き取る。
/// その方式で記録したとすると矛盾する分布は、時間帯別には使わず全体の統計にだけ残す
fn adopt_v1(store: &Store, watch: &str, aggregate_by: AggregateBy) -> Result<()> {
    let Some(v1) = store.v1_hist(watch)? else {
        return Ok(());
    };
    let plausible = v1_recorded_by(aggregate_by, &v1, store.probes_per_hour(watch)?);
    store.resolve_v1_hist(watch, plausible.then(|| aggregation_key(aggregate_by)))
}

/// 版 1 の分布が `aggregate_by` で記録されたとみて矛盾しないか。
/// `probes_per_hour` は保持期間内の probe の頻度で、止まっていた時間も均すので実際より少なめに出る
fn v1_recorded_by(aggregate_by: AggregateBy, v1: &V1Hist, probes_per_hour: f64) -> bool {
    if v1.min_bucket < 0 || v1.max_bucket > max_bucket(aggregate_by) {
        return false;
    }
    // bucket が範囲内でも、より粗い方式でも出る値（hour の 0..=23 や none の 0）しか無いと、
    // 範囲からは方式を区別できない。本当に `aggregate_by` で記録したなら、その bucket に当たる
    // 時刻にしか記録できていない（weekday_hour で 0..=23 だけなら月曜の 1 日、bucket 0 だけなら
    // 0 時台の 1 時間）。その 2 倍を超えるサンプルがあれば、粗い方式で何日分も記録したとみなす。
    // 頻度は少なめに出るので、迷う分布は引き取らない側に倒れる
    let hours = match aggregate_by {
        AggregateBy::WeekdayHour | AggregateBy::Hour if v1.max_bucket == 0 => 1.0,
        AggregateBy::WeekdayHour if v1.max_bucket <= 23 => 24.0,
        _ => return true,
    };
    v1.samples as f64 <= 2.0 * hours * probes_per_hour
}

fn bucket(aggregate_by: AggregateBy, time: DateTime<Local>) -> i64 {
    match aggregate_by {
        AggregateBy::WeekdayHour => {
            i64::from(time.weekday().num_days_from_monday()) * 24 + i64::from(time.hour())
        }
        AggregateBy::Hour => i64::from(time.hour()),
        AggregateBy::None => 0,
    }
}

fn local_time(ts: i64) -> DateTime<Local> {
    Local
        .timestamp_opt(ts, 0)
        .single()
        .unwrap_or_else(Local::now)
}

fn bin_of(value: f64) -> i64 {
    ((1.0 + value).ln() / BIN_RATIO.ln()).floor() as i64
}

/// ビンの中央値。ビン 0 はほぼ 0 の値（loss = 0 など）なので 0 に丸める
fn bin_value(bin: i64) -> f64 {
    if bin == 0 {
        return 0.0;
    }
    let lower = BIN_RATIO.powi(bin as i32);
    (lower + lower * BIN_RATIO) / 2.0 - 1.0
}

fn hist_percentile(hist: &[(i64, u64)], total: u64, fraction: f64) -> f64 {
    let rank = ((total as f64 * fraction).ceil() as u64).max(1);
    let mut seen = 0;
    for (bin, count) in hist {
        seen += count;
        if seen >= rank {
