//! 発火条件の式と、連続回数・クールダウンの判定。
//!
//! 式は `loss >= 0.5 || rtt_p50 > baseline.rtt_p95 * 2` のような形で、
//! 値が無い変数（データ不足のベースラインや、全滅時の RTT）を含む比較は
//! 「不明」になる。最終結果が不明なら発火しない。

use crate::config::{ProbeKind, Trigger};
use serde::Deserialize;
use std::collections::BTreeMap;

/// probe の種類ごとに、条件式で使える変数。
///
/// 式のパースでは検査しない。変数は probe の種類で決まり、パースの時点では
/// どの probe の式か分からないので、`Config::validate_watch` が照合する。
/// 網羅的に match しているのは、probe の種類を足したときに許可リストの決め忘れを防ぐため。
pub fn variables_for(kind: ProbeKind) -> &'static [&'static str] {
    match kind {
        ProbeKind::Tcp
        | ProbeKind::Icmp
        | ProbeKind::Dns
        | ProbeKind::Http
        | ProbeKind::Command => &[
            "loss",
            "rtt_p50",
            "rtt_p95",
            "rtt_max",
            "value",
            "baseline.rtt_p50",
            "baseline.rtt_p95",
            "baseline.loss_p50",
            "baseline.loss_p95",
            "baseline.value_p50",
            "baseline.value_p95",
        ],
        // process の変数は分類を組み込むタスクで埋める
        ProbeKind::Process => &[],
    }
}

