}

#[derive(Debug, Clone, Copy, PartialEq)]
enum CmpOp {
    Gt,
    Ge,
            e.variables(),
            ["loss", "rtt_p50", "baseline.rtt_p95", "value"]
        );
        assert!(expr("1 > 0").variables().is_empty());
    }

